  private parseUnary(): Expr {
    const t = this.peek();
    if (t.type === 'op' && (t.text === '+' || t.text === '-')) {
      this.next();
      const e = this.parseUnary();
      return t.text === '-' ? { k: 'neg', e } : e;
    }
    return this.parsePrimary();
