  private parsePrimary(): Expr {
    const t = this.peek();
    switch (t.type) {
      case 'number':
        this.next();
        if (!Number.isFinite(t.value)) {
          throw new LogoFailure('Liczba jest za duża.', at(t));
        }
        return { k: 'num', v: t.value };
      case 'colonvar':
        this.next();
        return this.checkedName(t);
      case 'word':
