      class: 'ed-input',
      spellcheck: 'false',
      autocomplete: 'off',
      autocapitalize: 'off',
      autocorrect: 'off',
      wrap: 'off',
      'aria-label': options.label,
      'aria-describedby': options.describedBy,
      'aria-multiline': 'true',
