    const text = this.textarea.value;
    if (text !== this.renderedText || this.renderedText === null) {
      this.renderedText = text;
      this.lines.innerHTML = this.renderLines(text);
      this.gutter.innerHTML = this.renderGutter(text);
    } else {
      this.markLines();
    }
    this.syncScroll();
  }

