        'a',
        { class: 'brand', href: '#/', 'aria-label': 'Logomocja, strona główna' },
        turtleIcon(),
        el('span', { class: 'brand-name', text: 'Logomocja' }),
        el('span', { class: 'brand-tag', text: 'studio żółwia' }),
      ),
