  color: var(--c-string);
}

.t-number {
  color: var(--c-number);
}

.t-command {
  color: var(--c-command);
  font-weight: 700;
}

.t-keyword {
  color: var(--c-keyword);
  font-weight: 700;
}

.t-procedure {
  color: var(--c-procedure);
  font-weight: 600;
}

.t-name {
  color: var(--c-name);
}

.t-bracket {
  color: var(--c-bracket);
  font-weight: 700;
}

.t-operator {
  color: var(--c-operator);
}

.t-error {
  color: var(--danger);
  text-decoration: underline wavy var(--danger);
}

.t-error-char {
  background: var(--danger-soft);
  text-decoration: underline wavy var(--danger);
  text-underline-offset: 3px;
}

/* ---- stage ---- */

.stage-host {
  position: relative;
  flex: 1;
  min-height: 300px;
  background: var(--canvas-bg);
  overflow: hidden;
}

.view {
  position: absolute;
  inset: 0;
}

.stage-canvas {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  outline: none;
  cursor: grab;
}

.stage-canvas:active {
  cursor: grabbing;
}

.stage-note {
  margin: 0;
  padding: 8px 12px;
  background: var(--danger-soft);
  color: var(--danger);
  font-size: 13px;
  border-bottom: 1px solid var(--line);
}

.stage-foot {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 4px 12px;
  padding: 8px 12px;
  border-top: 1px solid var(--line);
  font-size: 13px;
  color: var(--ink-soft);
}

.stage-info,
.turtle-info {
  margin: 0;
}

.turtle-info {
  font-family: var(--mono);
  font-size: 12px;
}

/* ---- status ---- */

.workspace-foot {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.status {
  margin: 0;
  color: var(--ink-soft);
  font-size: 14px;
}

.error-box {
  padding: 10px 12px;
  border: 1px solid var(--danger);
  border-radius: 10px;
  background: var(--danger-soft);
  color: var(--danger);
  font-size: 14px;
  font-weight: 600;
}

.shortcuts {
  margin: 0;
  color: var(--ink-soft);
  font-size: 13px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}

/* ---- toasts and dialogs ---- */

.toasts {
  position: fixed;
  right: 16px;
  bottom: 16px;
  z-index: 60;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-width: min(380px, calc(100vw - 32px));
}

.toast {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 12px;
  background: var(--ink);
  color: var(--paper);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.2);
  font-size: 14px;
}

.toast > span {
  flex: 1;
}

.toast .btn-link {
  color: var(--paper);
  font-weight: 700;
}

.toast .btn-icon {
  width: 28px;
  height: 28px;
  min-height: 28px;
  color: var(--paper);
  border: none;
  background: transparent;
}

dialog.dialog {
  width: min(640px, calc(100vw - 24px));
  max-height: 86vh;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--surface);
  color: var(--ink);
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.3);
}

dialog.dialog::backdrop {
  background: rgba(10, 18, 20, 0.5);
}

.dialog-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px 12px 18px;
  border-bottom: 1px solid var(--line);
}

.dialog-title {
  font-size: 22px;
}

.dialog-body {
  padding: 14px 18px 18px;
  overflow: auto;
  max-height: calc(86vh - 60px);
}

.dialog-body > p {
  margin-top: 0;
  color: var(--ink-soft);
}

.example-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.example-list h3 {
  margin-top: 10px;
  font-size: 17px;
}

.example-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--surface-2);
}

.example-card p {
  margin: 2px 0 0;
}

.example-name {
  color: var(--ink-soft);
  font-size: 13px;
}

.share-row {
  display: flex;
  gap: 8px;
}

.share-field {
  flex: 1;
  min-width: 0;
  padding: 8px 10px;
  border: 1px solid var(--line-strong);
  border-radius: 10px;
  background: var(--surface-2);
  color: var(--ink);
  font-family: var(--mono);
  font-size: 13px;
}

.shortcut-table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 12px;
}

.shortcut-table th,
.shortcut-table td {
  padding: 8px 6px;
  border-bottom: 1px solid var(--line);
  text-align: left;
  vertical-align: middle;
}

.shortcut-table th {
  width: 40%;
  font-weight: normal;
}

/* ---- challenges ---- */

.challenges {
  max-width: 1280px;
  margin: 0 auto;
  padding: 20px 18px 28px;
}

.challenges > h1 {
  font-size: 34px;
}

.lead {
  color: var(--ink-soft);
  max-width: 760px;
}

.challenge-layout {
  display: grid;
  grid-template-columns: 250px minmax(0, 1fr);
  gap: 16px;
  align-items: start;
}

.challenge-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.challenge-item {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--surface);
  color: var(--ink);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.challenge-item:hover {
  border-color: var(--line-strong);
}

.challenge-item[aria-current='true'] {
  border-color: var(--accent);
  background: var(--accent-soft);
}

.challenge-title {
  flex: 1;
  font-weight: 600;
}

.solved {
  color: var(--success);
  font-weight: 800;
}

.challenge-detail {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 16px 18px;
  min-width: 0;
}

.challenge-head {
  display: flex;
  align-items: center;
  gap: 10px;
}

.challenge-head h2 {
  font-size: 26px;
}

.task {
  font-size: 16px;
  margin: 10px 0;
}

.challenge-work {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 16px;
  margin-top: 12px;
}

.challenge-code {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
}

.challenge-code .editor-host {
  height: 320px;
  flex: none;
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

.challenge-stage-wrap {
  min-width: 0;
}

.challenge-stage {
  height: 100%;
  min-height: 360px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

.check-result {
  min-height: 0;
  padding: 0;
  border-radius: 10px;
  font-size: 14px;
  font-weight: 600;
}

.check-result:not(:empty) {
  padding: 10px 12px;
}

.check-result.is-pass {
  background: var(--success-soft);
  color: var(--success);
  border: 1px solid var(--success);
}

.check-result.is-fail {
  background: var(--danger-soft);
  color: var(--danger);
  border: 1px solid var(--danger);
}

.solution {
  border-top: 1px solid var(--line);
  padding-top: 10px;
}

.solution summary {
  cursor: pointer;
  font-weight: 600;
  color: var(--accent);
}

.code-sample {
  margin: 8px 0;
  padding: 10px 12px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: 10px;
  overflow: auto;
  font-size: 13px;
  line-height: 1.5;
  white-space: pre;
  color: var(--ink);
}

/* ---- reference ---- */

.prose {
  max-width: 980px;
  margin: 0 auto;
  padding: 24px 18px 40px;
}

.prose h1 {
  font-size: 36px;
  margin-bottom: 6px;
}

.prose h2 {
  font-size: 26px;
  margin: 34px 0 10px;
  padding-top: 6px;
  border-top: 1px solid var(--line);
}

.prose p {
  margin: 8px 0;
}

.prose .lead {
  font-size: 17px;
  margin-bottom: 14px;
}

.toc {
  padding: 12px 16px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

.toc ol {
  columns: 2;
  column-gap: 24px;
  margin: 8px 0 0;
  padding-left: 20px;
}

.toc a {
  color: var(--accent);
}

.table-wrap {
  overflow-x: auto;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.ref-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

.ref-table th,
.ref-table td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--line);
  text-align: left;
  vertical-align: top;
}

.ref-table thead th {
  background: var(--surface-2);
  font-size: 13px;
  color: var(--ink-soft);
}

.ref-table td:first-child {
  min-width: 180px;
}

.ref-table td code {
  font-size: 13px;
  color: var(--accent);
  font-weight: 700;
}

.ref-table p {
  margin: 0 0 6px;
}

.ref-example .code-sample {
  margin: 6px 0 2px;
  font-size: 12.5px;
}

.prose ul {
  padding-left: 20px;
}

.prose ol li {
  margin-bottom: 4px;
}

/* ---- responsive ---- */

@media (max-width: 960px) {
  .challenge-layout {
    grid-template-columns: 1fr;
  }

  .challenge-list {
    flex-direction: row;
    overflow-x: auto;
    padding-bottom: 4px;
  }

  .challenge-item {
    min-width: 200px;
  }

  .challenge-work {
    grid-template-columns: 1fr;
  }

  .toc ol {
    columns: 1;
  }
}

@media (max-width: 760px) {
  body {
    font-size: 16px;
  }

  :root {
    --ed-font: 16px;
    --ed-lh: 24px;
  }

  .site-head {
    padding: 8px 12px;
  }

  .brand-tag {
    display: none;
  }

  .head-tools {
    margin-left: 0;
  }

  .workspace {
    padding: 8px 10px 12px;
  }

  .workspace-main {
    grid-template-columns: 1fr;
    height: auto;
    min-height: 0;
  }

  .panel-code .editor-host {
    min-height: 52vh;
  }

  .stage-host {
    min-height: 56vh;
  }

  .toolbar-end {
    margin-left: 0;
  }

  .speed {
    width: 100px;
  }

  .example-card {
    grid-template-columns: 1fr;
  }

  .panel-hint {
    display: none;
  }

  .prose h1 {
    font-size: 30px;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
    animation: none !important;
  }
}
EOF
