  --line: #dcd2bd;
  --line-strong: #bfb294;
  --accent: #16866a;
  --accent-ink: #ffffff;
  --accent-soft: rgba(22, 134, 106, 0.12);
  --orange: #c1763d;
  --blue: #2b6fb3;
  --purple: #a478c0;
  --danger: #b3261e;
  --danger-soft: rgba(179, 38, 30, 0.1);
  --success: #1e7a4a;
  --success-soft: rgba(30, 122, 74, 0.12);
  --focus: #2b6fb3;
  --grid: rgba(29, 43, 47, 0.07);
  --grid-strong: rgba(29, 43, 47, 0.22);
  --axis: rgba(29, 43, 47, 0.3);
  --ghost: #9aa7a4;
