  --sans: system-ui, -apple-system, 'Segoe UI', Roboto, 'Noto Sans', 'Helvetica Neue', Arial, sans-serif;
  --serif: Georgia, 'Iowan Old Style', 'Palatino Linotype', 'Times New Roman', serif;
  --mono: ui-monospace, 'SFMono-Regular', Menlo, Consolas, 'Liberation Mono', monospace;
  --c-comment: #8b8f7d;
  --c-string: #a0491e;
  --c-number: #2b6fb3;
  --c-command: #16866a;
  --c-keyword: #8b4fb0;
  --c-procedure: #9a6b00;
  --c-name: #1d2b2f;
  --c-bracket: #6b5b3e;
  --c-operator: #7a6f5c;
  color-scheme: light;
}

:root[data-theme='dark'] {
  --paper: #0d1719;
  --surface: #13color;
  --surface-2: #182529;
  --canvas-bg: #0b1416;
  --ink: #e4ede8;
  --ink-soft: #97a8a4;
  --line: #2a3d43;
  --line-strong: #3d5459;
  --accent: #3cc49a;
  --accent-ink: #062018;
  --accent-soft: rgba(60, 196, 154, 0.14);
  --orange: #e0995e;
  --blue: #6aa8e8;
  --purple: #c49be0;
  --danger: #ff8a80;
  --danger-soft: rgba(255, 138, 128, 0.12);
  --success: #6fd39c;
  --success-soft: rgba(111, 211, 156, 0.14);
  --focus: #8cc4ff;
  --grid: rgba(228, 237, 232, 0.07);
