  --ghost: #5d7372;
  --turtle: #3cc49a;
  --selection: rgba(106, 168, 232, 0.3);
  --c-comment: #6f8582;
  --c-string: #f0a46f;
  --c-number: #8cc4ff;
  --c-command: #5fe0b4;
  --c-keyword: #d7a6f2;
  --c-procedure: #f0c96a;
  --c-name: #e4ede8;
  --c-bracket: #c8b48a;
  --c-operator: #a9b8b3;
  color-scheme: dark;
}

[hidden] {
  display: none !important;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
}

body {
  margin: 0;
  font-family: var(--sans);
  font-size: 15px;
  line-height: 1.5;
  color: var(--ink);
  background: var(--paper);
  display: flex;
  flex-direction: column;
  min-height: 100%;
}

#app {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

h1,
h2,
h3 {
