  height: 28px;
  color: var(--accent);
  align-self: center;
}

.brand-name {
  font-family: var(--serif);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.01em;
}

.brand-tag {
  color: var(--ink-soft);
  font-size: 13px;
}

.site-nav {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
}

.site-nav a {
  color: var(--ink-soft);
  text-decoration: none;
  padding: 6px 10px;
  border-radius: 999px;
  font-weight: 600;
}

.site-nav a:hover {
  color: var(--ink);
  background: var(--surface-2);
}

.site-nav a[aria-current='page'] {
  color: var(--accent);
  background: var(--accent-soft);
}

.head-tools {
  margin-left: auto;
  display: flex;
  gap: 8px;
}

.site-foot {
  margin-top: auto;
  padding: 10px 18px;
  color: var(--ink-soft);
  font-size: 13px;
  border-top: 1px solid var(--line);
}

main#main {
  flex: 1;
  min-height: 0;
  outline: none;
}

.route {
  min-height: 0;
}

/* ---- buttons ---- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 36px;
  padding: 6px 12px;
  border: 1px solid var(--line-strong);
  border-radius: 10px;
  background: var(--surface);
  color: var(--ink);
  font: inherit;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  text-decoration: none;
  white-space: nowrap;
}

.btn:hover:not(:disabled) {
