}

.btn-ghost {
  background: transparent;
  border-color: transparent;
}

.btn-ghost:hover:not(:disabled) {
  background: var(--surface-2);
  border-color: var(--line);
}

.btn-link {
  background: none;
  border: none;
  padding: 4px 2px;
  min-height: 0;
  color: var(--accent);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.btn-icon {
  width: 36px;
  padding: 0;
  font-size: 18px;
