}

.badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  padding: 1px 7px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--accent);
  vertical-align: middle;
}

.muted {
  color: var(--ink-soft);
}

/* ---- workspace ---- */

.workspace {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 12px 18px 14px;
  max-width: 1480px;
  width: 100%;
  margin: 0 auto;
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 14px;
  padding: 10px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

.toolbar-group {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.toolbar-end {
  margin-left: auto;
}

.seg {
