}

.seg-btn[aria-pressed='true'] {
  background: var(--accent);
  color: var(--accent-ink);
}

.seg-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.speed-wrap {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--ink-soft);
  font-size: 13px;
}

.speed {
  width: 130px;
  accent-color: var(--accent);
}

.workspace-main {
  display: grid;
