await page.goto(BASE, { waitUntil: 'load' });
await page.waitForFunction(() => window.logomocja !== undefined);
await page.waitForTimeout(200);

// 1. keyboard step / pause / reset
await ta().click();
await page.keyboard.press('Alt+K');
await page.waitForTimeout(100);
ok('Alt+K steps one statement', (await status()).includes('operacji: 1'), await status());
await page.keyboard.press('Alt+P');
await page.waitForTimeout(400);
const paused = await status();
ok('Alt+P pauses (no progress while paused)', (await page.locator('#view-edytor .status').textContent()) === paused && paused.startsWith('Wstrzymano') || paused.startsWith('Wykonywanie'), paused);
await page.keyboard.press('Alt+P');
await page.waitForTimeout(1500);
ok('Alt+P resumes to completion', (await status()).startsWith('Zakończono'), await status());
await page.keyboard.press('Alt+R');
await page.waitForTimeout(100);
ok('Alt+R resets to idle', (await status()).startsWith('Gotowe'), await status());

// 2. syntax error: marker, message, nothing drawn
await ta().fill('np 10\nnp 10 -5\n');
await page.waitForTimeout(500);
const boxText = await page.locator('#ws-error').textContent().catch(() => '');
ok('live parse error shows in error box', boxText.includes('linia 2, kolumna 7'), boxText);
ok('error line is marked', (await page.locator('#view-edytor .ed-line.is-error').count()) === 1);
await page.locator('#view-edytor button', { hasText: 'Uruchom' }).click();
await page.waitForTimeout(200);
const st = await status();
ok('parse error draws nothing', st.startsWith('Błąd w programie'), st);
ok('error character is marked in overlay', (await page.locator('#view-edytor .t-error-char').count()) === 1);

// 3. editing during a run marks the drawing stale
await ta().fill('powtorz 300 [np 5 pw 7]\n');
await page.locator('#view-edytor button', { hasText: 'Uruchom' }).click();
await page.waitForTimeout(300);
await ta().click();
await page.keyboard.type(' ');
await page.waitForTimeout(400);
ok('edit during run stops and marks stale', (await status()).includes('zmieniono'), await status());

// 4. drafts survive reload per mode
await ta().fill('np 42\n');
await page.waitForTimeout(500);
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(300);
ok('2D draft survives reload', (await ta().inputValue()) === 'np 42\n', JSON.stringify(await ta().inputValue()));
await page.locator('#view-edytor .seg-btn', { hasText: '3D' }).click();
await page.waitForTimeout(300);
await ta().fill('gora 10 np 3\n');
await page.waitForTimeout(500);
await page.locator('#view-edytor .seg-btn', { hasText: '2D' }).click();
await page.waitForTimeout(200);
ok('switching back to 2D restores its own draft', (await ta().inputValue()) === 'np 42\n');
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(300);
ok('mode persists across reload', (await page.locator('#view-edytor .seg-btn', { hasText: '2D' }).getAttribute('aria-pressed')) === 'true');

// 5. examples dialog keeps the previous draft recoverable
await page.locator('#view-edytor button', { hasText: 'Przykłady' }).click();
await page.locator('button[aria-label="Wczytaj przykład Gwiazda"]').click();
await page.waitForTimeout(400);
ok('example loaded into editor', (await ta().inputValue()).startsWith('; Sekret gwiazdy'));
const toastRestore = page.locator('.toast button', { hasText: 'Przywróć poprzedni tekst' });
ok('restore toast offered', (await toastRestore.count()) === 1);
await toastRestore.click();
await page.waitForTimeout(200);
ok('restore brings the previous draft back', (await ta().inputValue()) === 'np 42\n', JSON.stringify(await ta().inputValue()));

// 6. save and open .logo
const [download] = await Promise.all([page.waitForEvent('download'), page.locator('#view-edytor button', { hasText: 'Zapisz .logo' }).click()]);
const path = '/tmp/e2e/saved.logo';
await download.saveAs(path);
ok('save .logo downloads the program', download.suggestedFilename().endsWith('.logo'), download.suggestedFilename());
writeFileSync('/tmp/e2e/opened.logo', 'oto tr ma: a\n  powtorz 3 [np a pw 120]\njuż\ntr 50\n');
await page.locator('#view-edytor input[type=file]').setInputFiles('/tmp/e2e/opened.logo');
await page.waitForTimeout(400);
ok('open .logo loads file text', (await ta().inputValue()).startsWith('oto tr ma: a'));

// 7. PNG export
const [png] = await Promise.all([page.waitForEvent('download'), page.locator('#view-edytor button', { hasText: 'Uruchom' }).click().then(() => page.locator('#view-edytor button', { hasText: 'Eksport PNG' }).click())]);
ok('PNG export downloads', png.suggestedFilename().endsWith('.png'), png.suggestedFilename());

// 8. share dialog
await page.locator('#view-edytor button', { hasText: 'Udostępnij' }).click();
const link = await page.locator('.share-field').inputValue();
ok('share link has mode and program', link.includes('#/?m=2d&p='), link.slice(-30));
await page.keyboard.press('Escape');

// 9. theme toggle: manual dark
await page.locator('.head-tools button').click();
await page.locator('.head-tools button').click();
const theme = await page.evaluate(() => document.documentElement.dataset.theme);
ok('theme cycles to dark', theme === 'dark', theme);
await page.screenshot({ path: '/tmp/e2e/30-dark.png' });
await page.locator('.head-tools button').click();

// 10. mobile layout
const mob = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
mob.on('pageerror', (e) => errors.push('mobile pageerror: ' + e.message));
await mob.goto(BASE, { waitUntil: 'load' });
await mob.waitForFunction(() => window.logomocja !== undefined);
await mob.waitForTimeout(400);
await mob.screenshot({ path: '/tmp/e2e/31-mobile.png', fullPage: true });
const overflow = await mob.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
ok('no horizontal page overflow on phone', overflow <= 0, 'overflow=' + overflow);

console.log('errors:', errors.slice(0, 8));
await browser.close();
EOF
